package com.mamtrex.hospital.auth; import com.mamtrex.hospital.shared.BaseEntity; import jakarta.persistence.*; import java.util.*; @Entity @Table(name="user_accounts") public class UserAccount extends BaseEntity { @Column(nullable=false,unique=true) private String username; @Column(nullable=false) private String passwordHash; @ElementCollection(fetch=FetchType.EAGER) @Enumerated(EnumType.STRING) private Set<Role> roles=new HashSet<>(); private boolean enabled=true; protected UserAccount(){} public UserAccount(String u,String p,Set<Role> r){username=u;passwordHash=p;roles=r;} public String getUsername(){return username;} public String getPasswordHash(){return passwordHash;} public Set<Role> getRoles(){return roles;} public boolean isEnabled(){return enabled;} }
